 p_id=>wwv_flow_imp.id(123317509905929744)
,p_plug_name=>'POLIZAS'
,p_region_name=>'POLIZAS'
,p_parent_plug_id=>wwv_flow_imp.id(99464119120529442)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(123741082419162265)
,p_plug_display_sequence=>120
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    P.IDPOLIZA,',
'    P.NUMPOLUNICO,',
'    LTRIM(RTRIM(TRANSLATE(OC_CLIENTES.NOMBRE_CLIENTE(P.CODCLIENTE), '',       '', ''  ''))) AS NOM_CONTRATANTE,',
'    P.FECINIVIG,',
'    P.FECFINVIG,',
'    P.STSPOLIZA,',
'    P.TIPOADMINISTRACION,',
'    SUM(OC_DETALLE_POLIZA.TOTAL_ASEGURADOS(P.CODCIA, P.CODEMPRESA, P.IDPOLIZA, DP.IDETPOL)) AS TOTAL_ASEGURADOS,',
'    MIN(DP.IDETPOL) AS DETALLE_INICIO,',
'    MAX(DP.IDETPOL) AS DETALLE_FIN',
'FROM ',
'    POLIZAS P',
'INNER JOIN ',
'    DETALLE_POLIZA DP ',
'    ON P.CODCIA = DP.CODCIA ',
'    AND P.CODEMPRESA = DP.CODEMPRESA ',
'    AND P.IDPOLIZA = DP.IDPOLIZA',
'WHERE ',
'    (P.IDPOLIZA = :CONSECUTIVO OR P.NUMPOLUNICO = :NUMPOLUNICO)',
'    AND P.STSPOLIZA IN (''EMI'', ''REN'')',
'GROUP BY ',
'    P.IDPOLIZA,',
'    P.NUMPOLUNICO,',
'    P.CODCLIENTE,',
'    P.FECINIVIG,',
'    P.FECFINVIG,',
'    P.STSPOLIZA,',
'    P.TIPOADMINISTRACION;',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
