wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(99465007603529451)
,p_plug_name=>unistr('Hist\00F3rico Endoso')
,p_parent_plug_id=>wwv_flow_imp.id(99464858484529450)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(123741082419162265)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DESV.IDPOLIZA AS CONSECUTIVO,',
'DESV.IDETPOL AS CERTIFICADO,',
'DESV.IDENDOSO,',
'VALOR_ANTERIOR,',
'VALOR_ACTUAL,',
'STSENDOSO,',
'USUARIO,',
'TERMINAL,',
'FECH_ALTA',
'FROM DETALLE_ENDOSO_SV DESV',
'INNER JOIN ENDOSOS_SEGUIMIENTO ES ON DESV.IDPOLIZA = ES.IDPOLIZA AND DESV.IDENDOSO=ES.IDENDOSO',
'INNER JOIN ENDOSO_TEXTO ET ON DESV.IDPOLIZA = ET.IDPOLIZA AND DESV.IDENDOSO=ET.IDENDOSO',
'WHERE CAMPO =''TIPOADMINISTRACION''',
'ORDER BY FECH_ALTA DESC,7;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
