'   VALUES (:CONSECUTIVO, ''EN_PROCESO'', :APP_USER, :P1_IDETPOLINI, :P1_IDETPOLFIN)',
'   RETURNING ID_SOLICITUD INTO nIdSolicitud;',
'',
'   DBMS_SCHEDULER.create_job (',
'      job_name        => ''JOB_IMPRIMIR_CERT_'' || nIdSolicitud,',
'      job_type        => ''PLSQL_BLOCK'',',
'      job_action      => ''BEGIN PROCESAR_SOLICITUD_IMPRESION('' || nIdSolicitud || ''); END;'',',
'      start_date      => SYSTIMESTAMP,',
'      enabled         => TRUE,',
'      auto_drop       => TRUE',
'   );',
'END;',
''))
