wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(35745295342308946)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'New'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_blob BLOB;',
'BEGIN',
'  SELECT PDF_RESULTADO',
'  INTO v_blob',
'  FROM SOLICITUD_IMPRESION',
'  WHERE ID_SOLICITUD = :P3_ID_SOLICITUD;',
'',
'  owa_util.mime_header(''application/pdf'', FALSE);',
'  htp.p(''Content-Disposition: attachment; filename="Certificado_'' || :P3_IDPOLIZA || ''.pdf"'');',
'  owa_util.http_header_close;',
'',
'  wpg_docload.download_file(v_blob);',
'  apex_application.stop_apex_engine;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>35745295342308946
);
end;
